# Get mixed columns
def get_mixed_cols(grid, background):
    cols = len(grid[0])
    mixed = []
    for c in range(cols):
        col_vals = [grid[r][c] for r in range(len(grid))]
        if len(set(col_vals)) > 1:
            mixed.append(c)
    return sorted(mixed)

def transform_v8(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    counts = {}
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1
    background = max(counts.keys(), key=lambda k: counts[k])

    mixed_cols = get_mixed_cols(grid, background)

    if not mixed_cols:
        return [row[:] for row in grid]

    result = [row[:] for row in grid]

    # Find the 2-line
    separator_col = None
    for c in range(cols):
        col_vals = [grid[r][c] for r in range(rows)]
        elem = grid[0][c]
        unique_set = set(col_vals)
        if len(unique_set) == 1 and elem != background:
            separator_col = c
            break

    fill_col = None
    if separator_col is not None:
        if separator_col < min(mixed_cols):
            # Separator is left of mixed. Find first non-mixed AFTER mixed
            for c in range(max(mixed_cols) + 1, cols):
                col_vals = [grid[r][c] for r in range(rows)]
                if len(set(col_vals)) == 1 and col_vals[0] == background:
                    fill_col = c
                    break
        elif separator_col > max(mixed_cols):
            # Separator is right of mixed. Find first non-mixed BEFORE mixed
            for c in range(min(mixed_cols) - 1, -1, -1):
                col_vals = [grid[r][c] for r in range(rows)]
                if len(set(col_vals)) == 1 and col_vals[0] == background:
                    fill_col = c
                    break

    if fill_col is not None:
        for rr in range(rows):
            result[rr][fill_col] = 8

    return result

